UPDATE tasks SET status='FAILED',failed_stage=#{stage},error_code=#{code},error_message=#{message},
                 finished_at=#{now},version=version+1
WHERE id=#{id} AND status='RUNNING' AND current_stage=#{stage}

UPDATE task_steps SET status='FAILED',started_at=COALESCE(started_at,#{now}),
                      finished_at=#{now},error_message=#{message}
WHERE task_id=#{id} AND stage=#{stage} AND status IN ('PENDING','RUNNING')
